import { motion } from "framer-motion";
import { ArrowRight, AlertTriangle, ScanSearch, Scale, FileCheck2, Check, EyeOff, Eye } from "lucide-react";
import { useEffect, useState } from "react";

const initialSignals = [
  { l: "GitHub commits: 3", v: "weak", s: "neg" },
  { l: "Slack volume: low", v: "low", s: "neg" },
  { l: "Activity: 412 events", v: "−18% vs median", s: "neg" },
  { l: "Missed deadline (Mar 14)", v: "−6 pts", s: "neg" },
];

const fullSignals = [
  { l: "Influenced campaign revenue", v: "+8 pts", s: "pos" },
  { l: "Cross-functional launches", v: "+6 pts", s: "pos" },
  { l: "Client saves & touchpoints", v: "+5 pts", s: "pos" },
  { l: "Mentoring & onboarding", v: "+4 pts", s: "pos" },
  { l: "Off-channel collaboration", v: "+3 pts", s: "pos" },
  { l: "Missed deadline (Mar 14), retained", v: "−6 pts", s: "neg" },
];

export default function Hero({ onRunDemo }: { onRunDemo: () => void }) {
  const [showFull, setShowFull] = useState(false);
  const [score, setScore] = useState(32);

  useEffect(() => {
    const t = setInterval(() => setShowFull((v) => !v), 5000);
    return () => clearInterval(t);
  }, []);

  useEffect(() => {
    const target = showFull ? 58 : 32;
    const start = score;
    const diff = target - start;
    let raf: number;
    const t0 = performance.now();
    const animate = (t: number) => {
      const p = Math.min(1, (t - t0) / 1000);
      const eased = 1 - Math.pow(1 - p, 3);
      setScore(Math.round(start + diff * eased));
      if (p < 1) raf = requestAnimationFrame(animate);
    };
    raf = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(raf);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [showFull]);

  return (
    <section id="top" className="relative overflow-hidden pt-[104px] md:pt-[132px] pb-12 md:pb-16">
      <div className="absolute inset-0 grid-bg" />

      <div className="relative mx-auto max-w-[1280px] px-6 md:pl-2 md:pr-10">
        <div className="grid lg:grid-cols-[1.02fr_0.98fr] gap-12 lg:gap-14 items-start pt-10 md:pt-14">
          <div>
            <motion.h1
              initial={{ opacity: 0, y: 18 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.07 }}
              className="text-[42px] leading-[0.98] md:text-[68px] font-bold tracking-[-0.032em] text-[#15181c]"
            >
              What if AI judged you{" "}
              <span className="relative inline-block">
                <span className="text-[#9b9488] line-through decoration-[#b23a2e] decoration-[4px]">
                  without
                </span>
              </span>{" "}
              seeing the{" "}
              <span className="relative inline-block text-[#1b3a5c]">
                whole picture?
                <span className="absolute left-0 -bottom-1.5 h-[3px] w-full bg-[#1b3a5c]/25" />
              </span>
            </motion.h1>

            <motion.p
              initial={{ opacity: 0, y: 18 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.14 }}
              className="mt-7 max-w-[560px] text-[16px] md:text-[18px] leading-[1.65] text-[#4a443b]"
            >
              <strong className="text-[#15181c] font-semibold">WholePicture</strong> finds the evidence AI
              missed, lets <strong className="text-[#15181c] font-semibold">both employees and managers</strong>{" "}
              challenge the assessment, and shows exactly{" "}
              <span className="text-[#1b3a5c] font-semibold underline decoration-[#1b3a5c]/35 underline-offset-[5px]">
                what changed, and why.
              </span>
            </motion.p>

            <motion.div
              initial={{ opacity: 0, y: 18 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.2 }}
              className="mt-8 flex flex-col sm:flex-row gap-3"
            >
              <button
                onClick={onRunDemo}
                className="group inline-flex items-center justify-center gap-2.5 bg-[#1b3a5c] px-7 py-3.5 text-[14.5px] font-semibold text-[#f7f5f1] hover:bg-[#15181c] transition-colors"
              >
                See the demo
                <ArrowRight className="h-4 w-4 transition-transform group-hover:translate-x-1" />
              </button>
              <a
                href="#how"
                className="inline-flex items-center justify-center gap-2.5 border border-[#15181c]/25 bg-white px-7 py-3.5 text-[14.5px] font-semibold text-[#15181c] hover:border-[#15181c] transition-colors"
              >
                <FileCheck2 className="h-4 w-4" />
                How it works
              </a>
            </motion.div>

            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ delay: 0.32 }}
              className="mt-9 grid grid-cols-1 sm:grid-cols-3 border-t border-[#ded8ce] pt-5 gap-5 sm:gap-6"
            >
              {[
                { k: "Find", v: "Evidence the initial model never saw", icon: ScanSearch, tone: "text-[#1b3a5c]" },
                { k: "Challenge", v: "Two-sided contest by employee and manager", icon: Scale, tone: "text-[#9a6b1c]" },
                { k: "Prove", v: "Every change logged, nothing quietly erased", icon: AlertTriangle, tone: "text-[#3c6b4a]" },
              ].map((s) => (
                <div key={s.v}>
                  <s.icon className={`h-4 w-4 mb-2 ${s.tone}`} />
                  <div className="text-[22px] leading-none font-bold tracking-[-0.02em] text-[#15181c]">{s.k}</div>
                  <div className="mt-1.5 text-[12px] leading-[1.45] text-[#6e675c]">{s.v}</div>
                </div>
              ))}
            </motion.div>
          </div>

          {/* RIGHT, assessment card */}
          <motion.div
            initial={{ opacity: 0, y: 26 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.18, duration: 0.6 }}
            className="relative lg:mt-2"
          >
            <div className="absolute inset-0 translate-x-3 translate-y-3 border border-[#ded8ce] bg-[#efece5]" />
            <div className="relative panel">
              <div className="flex items-center justify-between border-b border-[#ded8ce] px-5 py-4">
                <div className="flex items-center gap-3">
                  <img
                    src="/images/sarah.jpg"
                    alt="Sarah Lim"
                    className="h-11 w-11 object-cover border border-[#ded8ce] grayscale-[35%]"
                  />
                  <div>
                    <div className="text-[15px] font-semibold leading-tight text-[#15181c]">
                      Sarah Lim
                    </div>
                    <div className="text-[12px] text-[#6e675c] mt-0.5">Marketing Executive · H1 cycle</div>
                  </div>
                </div>
                <motion.div
                  key={showFull ? "mod" : "low"}
                  initial={{ scale: 1.15, opacity: 0.4 }}
                  animate={{ scale: 1, opacity: 1 }}
                  transition={{ duration: 0.35 }}
                  className={`stamp text-[11px] ${showFull ? "text-[#3c6b4a]" : "text-[#b23a2e]"}`}
                >
                  {showFull ? "Moderate" : "Low"}
                </motion.div>
              </div>

              <div className="px-5 pt-4">
                <div className="grid grid-cols-2 border border-[#ded8ce] bg-[#efece5]">
                  <button
                    onClick={() => setShowFull(false)}
                    className={`flex items-center justify-center gap-1.5 py-2 text-[11.5px] font-semibold transition-colors ${
                      !showFull ? "bg-white text-[#15181c] border-r border-[#ded8ce]" : "text-[#9b9488] border-r border-[#ded8ce]"
                    }`}
                  >
                    <EyeOff className="h-3.5 w-3.5" /> Partial view
                  </button>
                  <button
                    onClick={() => setShowFull(true)}
                    className={`flex items-center justify-center gap-1.5 py-2 text-[11.5px] font-semibold transition-colors ${
                      showFull ? "bg-[#1b3a5c] text-[#f7f5f1]" : "text-[#9b9488]"
                    }`}
                  >
                    <Eye className="h-3.5 w-3.5" /> Whole picture
                  </button>
                </div>
              </div>

              <div className="px-5 pt-5">
                <div className="flex items-end justify-between">
                  <div>
                    <div className="label text-[9px] text-[#9b9488]">Contribution score</div>
                    <div className="text-[56px] leading-[0.85] font-bold tracking-[-0.035em] text-[#15181c] mt-2">
                      {score}
                      <span className="text-[18px] font-medium text-[#9b9488]">/100</span>
                    </div>
                  </div>
                  <div className="text-right pb-1">
                    <div className={`text-[12px] font-semibold ${showFull ? "text-[#3c6b4a]" : "text-[#b23a2e]"}`}>
                      {showFull ? "Meets bar, growth areas" : "Below contribution bar"}
                    </div>
                    <div className="label text-[9px] text-[#9b9488] mt-1.5">
                      {showFull ? "9 signals · fuller coverage" : "4 signals · partial coverage"}
                    </div>
                  </div>
                </div>

                <div className="mt-4">
                  <div className="relative h-2.5 bg-[#efece5] border border-[#ded8ce]">
                    <motion.div
                      className={`h-full transition-[width] duration-500 ${
                        showFull ? "bg-[#3c6b4a]" : "bg-[#b23a2e]"
                      }`}
                      style={{ width: `${score}%` }}
                    />
                    <div className="absolute inset-y-0 left-[40%] w-px bg-[#15181c]/35" />
                    <div className="absolute inset-y-0 left-[65%] w-px bg-[#15181c]/35" />
                  </div>
                  <div className="mt-1.5 flex justify-between label text-[8.5px] text-[#9b9488]">
                    <span>0</span>
                    <span>40 Moderate</span>
                    <span>65 High</span>
                    <span>100</span>
                  </div>
                </div>
              </div>

              <div className="px-5 pt-5">
                <div className="label text-[9px] text-[#9b9488] pb-1.5 border-b border-[#15181c]">
                  Signals on record
                </div>
                <table className="w-full">
                  <tbody>
                    {(showFull ? fullSignals : initialSignals).map((s) => (
                      <tr key={s.l} className="border-b border-[#ded8ce]">
                        <td className="py-[7px] pr-3 text-[12px] text-[#4a443b] leading-snug">
                          <span
                            className={`inline-block h-[6px] w-[6px] mr-2 align-middle ${
                              s.s === "pos" ? "bg-[#3c6b4a]" : "bg-[#b23a2e]"
                            }`}
                          />
                          {s.l}
                        </td>
                        <td
                          className={`py-[7px] text-right text-[11px] font-semibold whitespace-nowrap ${
                            s.s === "pos" ? "text-[#3c6b4a]" : "text-[#b23a2e]"
                          }`}
                        >
                          {s.v}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>

              <div
                className={`mt-4 border-t border-[#ded8ce] px-5 py-3.5 flex items-start gap-2.5 text-[12px] leading-[1.5] ${
                  showFull ? "bg-[#3c6b4a]/[0.07] text-[#2d5239]" : "bg-[#b23a2e]/[0.07] text-[#8e2c22]"
                }`}
              >
                {showFull ? (
                  <>
                    <Check className="h-4 w-4 shrink-0 mt-0.5" strokeWidth={2.5} />
                    <span>
                      <strong>Missing proofs recovered.</strong> Delivery concern retained on record, not erased.
                    </span>
                  </>
                ) : (
                  <>
                    <AlertTriangle className="h-4 w-4 shrink-0 mt-0.5" />
                    <span>
                      <strong>Incomplete basis.</strong> Only part of the work surface observed. Label not yet justified.
                    </span>
                  </>
                )}
              </div>
            </div>
          </motion.div>
        </div>

        <div id="problem" className="mt-16 md:mt-20 scroll-mt-24">
          <div className="grid md:grid-cols-[190px_1fr] gap-6 md:gap-10 border-t-2 border-[#15181c] pt-7">
            <div>
              <div className="label text-[9.5px] text-[#b23a2e]">The core failure mode</div>
            </div>
            <p className="text-[20px] md:text-[28px] leading-[1.32] font-medium tracking-[-0.015em] text-[#15181c] max-w-3xl">
              AI can make <span className="text-[#b23a2e]">high-impact workforce decisions</span> on{" "}
              <span className="underline decoration-[#1b3a5c] decoration-2 underline-offset-[6px]">
                incomplete data
              </span>
              , missing context, or inaccurate signals about actual work.
            </p>
          </div>
        </div>
      </div>

      {/* full-width separator */}
      <div className="absolute inset-x-0 bottom-0 h-px bg-[#ded8ce]" />
    </section>
  );
}
